WITH p AS (SELECT %s::date d1,%s::date d2,coalesce(%s::text,'') ma_vt,%s::integer uid,%s::integer lim),s AS (SELECT p.*,u.user_id ok,coalesce(u.ds_branchs,'') bs,coalesce(u.is_super,0)=1 OR (coalesce(u.ds_branchs,'')='' AND coalesce(u.ds_stocks,'')='') unrestricted FROM p LEFT JOIN public.userinfo u ON u.user_id=p.uid) SELECT a.id_material,a.id_oi,a.mes_scheduling_code,a.product_code,a.material_code,a.material_name,a.ma_lo,a.ma_lo_ncc,a.seri,a.so_luong,a.sl_su_dung,a.sl_con_lai,a.create_date,a.create_time,a.status,count(*) OVER() total FROM public.mes_oi_material a CROSS JOIN s WHERE s.ok IS NOT NULL AND a.create_date BETWEEN s.d1 AND s.d2 AND(s.ma_vt='' OR a.material_code=ANY(string_to_array(s.ma_vt,','))) AND (s.unrestricted OR EXISTS(SELECT 1 FROM public.mes_oi_confirm c WHERE c.id_oi=a.id_oi AND c.branch_code=ANY(string_to_array(s.bs,',')))) ORDER BY a.create_date DESC,a.create_time DESC LIMIT(SELECT lim FROM p);
